B.a8F=s(["Robot","Robot","Roboter","Rob\xf4","\u30ed\u30dc\u30c3\u30c8","\u0930\u094b\u092c\u094b\u091f","Robot","Robot"],t.s)
B.a5K=s(["Remoto","Distant","Remote","Remoto","\u30ea\u30e2\u30fc\u30c8","\u0930\u093f\u092e\u094b\u091f","Jarak jauh","T\u1eeb xa"],t.s)
B.a0i=s(["Tipo: {0}","Type : {0}","Typ: {0}","Tipo: {0}","\u30bf\u30a4\u30d7: {0}","\u092a\u094d\u0930\u0915\u093e\u0930: {0}","Jenis: {0}","Lo\u1ea1i: {0}"],t.s)
B.fG=s(["Jugador {0}","Joueur {0}","Spieler {0}","Jogador {0}","\u30d7\u30ec\u30a4\u30e4\u30fc{0}","\u0916\u093f\u0932\u093e\u0921\u093c\u0940 {0}","Pemain {0}","Ng\u01b0\u1eddi ch\u01a1i {0}"],t.s)
